import { test, expect, type Page } from '@playwright/test'
import { execFileSync } from 'node:child_process'
import { fileURLToPath } from 'node:url'
import { join } from 'node:path'

// These bytes are generated by the isolated synthetic test helper, never by a dataset/model.
const backend = fileURLToPath(new URL('../../backend/', import.meta.url))
const python = process.env.KNEEOAI_TEST_PYTHON ?? join(backend, '.venv', process.platform === 'win32' ? 'Scripts/python.exe' : 'bin/python')
let dicom: Buffer, tinyPng: Buffer
const referenceNote = 'La fuente sintética original y su mitad fueron inspeccionadas en ambas ventanas antes de ver cualquier recorte.'
const observationNote = 'Inspección exclusivamente sintética del original, de la mitad y de ambos recortes, con observaciones completas para probar el software.'

test.beforeAll(() => {
  dicom = execFileSync(python, ['-c', 'import sys;sys.path.insert(0,sys.argv[1]);from synthetic_dicoms import dicom_bytes;sys.stdout.buffer.write(dicom_bytes())', join(backend, 'tests')], { cwd: backend, maxBuffer: 10 * 1024 * 1024 })
  tinyPng = execFileSync(python, ['-c', 'import io,sys;from PIL import Image;b=io.BytesIO();Image.new("L",(1,1),0).save(b,format="PNG");sys.stdout.buffer.write(b.getvalue())'], { cwd: backend })
})

async function login(page: Page) {
  await page.goto('/acceso')
  await page.locator('#login-email').fill('browser-a@kneeoai.invalid')
  await page.locator('#login-password').fill('BrowserTestsOnly-2026!')
  await page.getByRole('button', { name: 'Iniciar sesión', exact: true }).click()
  await expect(page.getByRole('heading', { name: 'Mis evaluaciones', exact: true })).toBeVisible()
}
async function createCase(page: Page) {
  await login(page)
  await page.getByRole('button', { name: 'Nueva evaluación', exact: true }).click()
  await page.locator('#draft-age').fill('62')
  await page.locator('#draft-sex').selectOption('F')
  // An absent BMI remains absent; the image workflow must not invent a complete-case rule.
  await page.locator('#draft-knee-right').check()
  const saved = page.waitForResponse(response => response.request().method() === 'POST' && new URL(response.url()).pathname === '/api/v1/evaluations')
  await page.getByRole('button', { name: 'Guardar y continuar', exact: true }).click()
  const response = await saved
  expect(response.status()).toBe(201)
  const evaluation = await response.json()
  expect(evaluation.clinical.bmi).toBeNull()
  await expect(page.locator('#dicom-file')).toBeEnabled()
  return evaluation as { id: string; code: string }
}
async function selectDicom(page: Page) {
  await page.locator('#dicom-file').setInputFiles({ name: 'synthetic-only.dcm', mimeType: 'application/dicom', buffer: dicom })
}
async function waitForSource(page: Page) {
  for (const [view, width] of [['full_a', 802], ['full_b', 802], ['half_a', 401], ['half_b', 401]] as const) {
    await expect(page.locator(`[data-view="${view}"] img`)).toHaveJSProperty('naturalWidth', width)
  }
  await expect(page.locator('#seal-reference')).toBeEnabled()
}
async function upload(page: Page) {
  await selectDicom(page)
  const saved = page.waitForResponse(response => response.request().method() === 'POST' && new URL(response.url()).pathname.endsWith('/preparations'))
  await page.getByRole('button', { name: 'Cargar DICOM', exact: true }).click()
  const response = await saved
  expect([200, 202]).toContain(response.status())
  const preparation = await response.json()
  await waitForSource(page)
  return preparation as { id: string; preparationRevisionId: string }
}
async function fillReference(page: Page, resolved = true) {
  await page.locator('#reference-confirm-side').check()
  await page.locator('#reference-resolved').selectOption(resolved ? 'resolved' : 'unresolved')
  if (resolved) {
    const half = page.locator('[data-view="half_a"] img')
    const rect = await half.boundingBox()
    expect(rect).not.toBeNull()
    await half.click({ position: { x: rect!.width / 2, y: rect!.height / 2 } })
    const clickedX = Number(await page.locator('#reference-center-x').inputValue())
    const clickedY = Number(await page.locator('#reference-center-y').inputValue())
    expect(Number.isInteger(clickedX) && Number.isInteger(clickedY)).toBe(true)
    expect(Math.abs(clickedX - 200)).toBeLessThanOrEqual(1)
    expect(Math.abs(clickedY - 120)).toBeLessThanOrEqual(1)
    // A CSS pointer can land on either side of a pixel edge. The accessible inputs
    // set the exact synthetic reference without altering the frozen coordinate rules.
    await page.locator('#reference-center-x').fill('200')
    await page.locator('#reference-center-y').fill('120')
  }
  await page.locator('#reference-inspected').check()
  await page.locator('#reference-blinded').check()
  await page.locator('#reference-note').fill(referenceNote)
}
async function sealReference(page: Page) {
  await fillReference(page)
  const saved = page.waitForResponse(response => response.request().method() === 'POST' && new URL(response.url()).pathname.endsWith('/reference'))
  await page.locator('#seal-reference').click()
  const response = await saved
  expect(response.status()).toBe(201)
  await expect(page.locator('#continue-quality-review')).toBeEnabled()
  return response.json()
}
async function enterReview(page: Page) {
  await page.locator('#continue-quality-review').click()
  await expect(page.getByRole('heading', { name: 'Revisión del recorte', exact: true })).toBeVisible()
  for (const [view, width] of [['full_a', 802], ['full_b', 802], ['half_a', 401], ['half_b', 401], ['crop_a', 200], ['crop_b', 200]] as const) {
    await expect(page.locator(`[data-view="${view}"] img`)).toHaveJSProperty('naturalWidth', width)
  }
  await expect(page.locator('#qc-confirm-side')).toBeEnabled()
}
async function completeObservation(page: Page, effect = 'none') {
  await page.locator('#qc-confirm-side').check()
  for (const field of ['side_supported', 'coverage_complete', 'lateral_margins_visible']) await page.locator(`#qc-${field}`).selectOption('yes')
  for (const field of ['physical_origin_known', 'unclassified_mark_present']) await page.locator(`#qc-${field}`).selectOption('no')
  for (const field of ['medial_joint_borders', 'lateral_joint_borders', 'subchondral_bone']) await page.locator(`#qc-${field}`).selectOption('visible')
  await page.locator('#qc-hardware').selectOption('absent')
  await page.locator('#qc-text_or_mask').selectOption('absent')
  await page.locator('#qc-mark_effect').selectOption(effect)
  await page.locator('#qc-note').fill(observationNote)
  for (const field of ['original_half_inspected', 'both_windows_inspected', 'outcome_blinded']) await page.locator(`#qc-${field}`).check()
}
async function prepareReview(page: Page) { const evaluation = await createCase(page); const preparation = await upload(page); await sealReference(page); await enterReview(page); return { evaluation, preparation } }

test('DICOM source is inspected and sealed before ROI, then full QC persists across reload and logout', async ({ page }) => {
  const roiRequests: string[] = [], predictorRequests: string[] = []
  page.on('request', request => { if (/\/views\/crop_[ab]\?/.test(request.url())) roiRequests.push(request.url()); if (/\/executions(?:\?|$)/.test(request.url())) predictorRequests.push(request.url()) })
  const evaluation = await createCase(page)
  const preparation = await upload(page)
  await page.screenshot({ path: 'test-results/phase3-source-desktop.png', fullPage: true })
  await page.setViewportSize({ width: 375, height: 844 })
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true)
  await page.setViewportSize({ width: 1440, height: 1000 })
  expect(roiRequests).toHaveLength(0)
  const reference = await sealReference(page)
  expect(reference.centerXY).toEqual([200, 120])
  expect(reference.originalAndHalfInspected).toBe(true)
  expect(roiRequests).toHaveLength(0)
  await expect(page.locator('#reference-center-x')).toHaveCount(0)
  await enterReview(page)
  await completeObservation(page)
  await page.screenshot({ path: 'test-results/phase3-review-desktop.png', fullPage: true })
  await page.setViewportSize({ width: 375, height: 844 })
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true)
  const saved = page.waitForResponse(response => response.request().method() === 'POST' && new URL(response.url()).pathname.endsWith('/reviews'))
  await page.locator('#submit-qc-accepted').click()
  const response = await saved
  expect(response.status()).toBe(201)
  const posted = response.request().postDataJSON()
  expect(posted.observation).toMatchObject({ side_supported: true, coverage_complete: true, visibility: { medial_joint_borders: 'visible', lateral_joint_borders: 'visible', subchondral_bone: 'visible' }, both_windows_inspected: true, outcome_blinded: true })
  expect(posted.observation).not.toHaveProperty('knee_alias')
  const review = await response.json()
  expect(review.assessment.accepted).toBe(true)
  await expect(page).toHaveURL(new RegExp(`/evaluaciones/${evaluation.id}/resumen$`))
  await expect(page.locator('#summary-review-status')).toHaveText('Aceptado por el procedimiento QC')
  await expect(page.locator('.summary-review-details')).toContainText(review.id)
  await expect(page.getByRole('button', { name: 'Calcular predicción', exact: true })).toBeDisabled()
  await page.reload()
  await expect(page.locator('#summary-review-status')).toHaveText('Aceptado por el procedimiento QC')
  const server = await page.request.get(`/api/v1/preparations/${preparation.id}`)
  const stored = await server.json()
  expect(stored.activeReview.id).toBe(review.id)
  expect(stored.activeReview.observation.note).toBe(observationNote)
  await expect(page.locator('img[src*="/demo/"]')).toHaveCount(0)
  await page.screenshot({ path: 'test-results/phase3-summary-mobile.png', fullPage: true })
  expect(await page.evaluate(() => document.documentElement.scrollWidth <= window.innerWidth)).toBe(true)
  await page.getByRole('button', { name: 'Cerrar sesión', exact: true }).click()
  await expect(page).toHaveURL(/\/acceso$/)
  await login(page)
  await page.getByRole('link', { name: `Ver resumen del caso ${evaluation.code}`, exact: true }).click()
  await expect(page.locator('#summary-review-status')).toHaveText('Aceptado por el procedimiento QC')
  expect(predictorRequests).toEqual([])
})

test('incomplete source inspection never seals and an unresolved reference stays sealed without ROI', async ({ page }) => {
  const referencePosts: string[] = [], roiRequests: string[] = []
  page.on('request', request => { if (request.method() === 'POST' && request.url().endsWith('/reference')) referencePosts.push(request.url()); if (/\/views\/crop_[ab]\?/.test(request.url())) roiRequests.push(request.url()) })
  await createCase(page)
  const preparation = await upload(page)
  await page.locator('#seal-reference').click()
  await expect(page.locator('#preparation-error')).toBeVisible()
  expect(referencePosts).toHaveLength(0)
  await fillReference(page, false)
  const saved = page.waitForResponse(response => response.request().method() === 'POST' && new URL(response.url()).pathname.endsWith('/reference'))
  await page.locator('#seal-reference').click()
  expect((await saved).status()).toBe(201)
  await expect(page.locator('#continue-quality-review')).toBeDisabled()
  await page.reload()
  await expect(page.getByRole('heading', { name: 'Referencia sellada', exact: true })).toBeVisible()
  await expect(page.locator('#reference-center-x')).toHaveCount(0)
  const stored = await (await page.request.get(`/api/v1/preparations/${preparation.id}`)).json()
  expect(stored.sourceReference.centerResolved).toBe(false)
  expect(stored.sourceReference.centerXY).toBeNull()
  expect(stored.activeReview).toBeNull()
  expect(roiRequests).toHaveLength(0)
})

test('QC requires complete observations, and the backend can reject them before an administrative rejection is saved', async ({ page }) => {
  const { preparation } = await prepareReview(page)
  await page.locator('#qc-confirm-side').check()
  await page.locator('#submit-qc-accepted').click()
  await expect(page.locator('#quality-review-error')).toContainText('Completa todas las observaciones')
  await completeObservation(page)
  await page.locator('#qc-side_supported').selectOption('no')
  const blocked = page.waitForResponse(response => response.request().method() === 'POST' && new URL(response.url()).pathname.endsWith('/reviews'))
  await page.locator('#submit-qc-accepted').click()
  expect((await blocked).status()).toBe(409)
  await expect(page.locator('#quality-review-error')).toBeVisible()
  await expect(page.locator('#qc-note')).toHaveValue(observationNote)
  expect((await (await page.request.get(`/api/v1/preparations/${preparation.id}`)).json()).activeReview).toBeNull()
  await page.locator('#submit-qc-rejected').click()
  await expect(page.locator('#quality-review-error')).toContainText('motivo de rechazo')
  await page.locator('#qc-rejection-reason').fill('Rechazo administrativo ficticio para verificar que el servidor no inventa observaciones de calidad.')
  const rejected = page.waitForResponse(response => response.request().method() === 'POST' && new URL(response.url()).pathname.endsWith('/reviews'))
  await page.locator('#submit-qc-rejected').click()
  const response = await rejected
  expect(response.status()).toBe(201)
  expect(response.request().postDataJSON().observation).toBeNull()
  const review = await response.json()
  expect(review.assessment).toBeNull()
  await expect(page.locator('#summary-review-status')).toHaveText('Rechazo administrativo')
  await page.reload()
  await expect(page.locator('#summary-review-status')).toHaveText('Rechazo administrativo')
})

test('a point captured at the crop center maps to native-half XYXY coordinates, not zero-origin crop pixels', async ({ page }) => {
  const { preparation } = await prepareReview(page)
  const metadata = await (await page.request.get(`/api/v1/preparations/${preparation.id}`)).json()
  expect(metadata.cropGeometry.nativeHalfBox).toEqual([100, 70, 300, 170])
  await page.locator('#qc-mark-peripheral_ruler').check()
  await page.locator('#qc-ruler_outside_bone').selectOption('yes')
  await page.locator('[data-view="crop_a"]').getByRole('button', { name: 'Ver a tamaño nativo', exact: true }).click()
  const crop = page.locator('[data-view="crop_a"] img'), rect = await crop.boundingBox()
  expect(rect).not.toBeNull()
  await crop.evaluate(image => image.addEventListener('click', event => {
    const measured = image.getBoundingClientRect()
    // Public fixture geometry is XYXY [100,70,300,170]. Use the real browser
    // event to account for integer CSS mouse coordinates and fractional layout.
    const x = 100 + (event.clientX - measured.left) / measured.width * 200
    const y = 70 + (event.clientY - measured.top) / measured.height * 100
    ;(window as Window & { syntheticRulerExpected?: [number, number] }).syntheticRulerExpected = [Math.round(x * 100) / 100, Math.round(y * 100) / 100]
  }, { once: true }))
  await crop.click({ position: { x: rect!.width / 2, y: rect!.height / 2 } })
  const expectedPoint = await page.evaluate(() => (window as Window & { syntheticRulerExpected?: [number, number] }).syntheticRulerExpected!)
  expect(Math.abs(expectedPoint[0] - 200)).toBeLessThanOrEqual(1)
  expect(Math.abs(expectedPoint[1] - 120)).toBeLessThanOrEqual(1)
  await expect(page.locator('#ruler-x-0')).toHaveValue(String(expectedPoint[0]))
  await expect(page.locator('#ruler-y-0')).toHaveValue(String(expectedPoint[1]))
  await completeObservation(page, 'non_obscuring')
  const saved = page.waitForResponse(response => response.request().method() === 'POST' && new URL(response.url()).pathname.endsWith('/reviews'))
  await page.locator('#submit-qc-accepted').click()
  const response = await saved
  expect(response.status()).toBe(201)
  expect(response.request().postDataJSON().observation.ruler_locations_xy).toEqual([expectedPoint])
  expect((await response.json()).observation.ruler_locations_xy).toEqual([expectedPoint])
})

test('a PNG whose dimensions contradict the declared preview cannot unlock acceptance', async ({ page }) => {
  await createCase(page); await upload(page); await sealReference(page)
  await page.route('**/views/crop_a?*', route => route.fulfill({ status: 200, contentType: 'image/png', body: tinyPng }))
  await page.locator('#continue-quality-review').click()
  await expect(page.getByText('Las dimensiones de la vista no coinciden con las declaradas por el servidor. La inspección queda bloqueada.', { exact: true })).toBeVisible()
  await expect(page.locator('#submit-qc-accepted')).toBeDisabled()
})

test('a lost upload response reuses its intent and recovers the same persisted preparation', async ({ page }) => {
  const evaluation = await createCase(page)
  const attempts: { key: string | undefined; preparationId: string; status: number }[] = []
  await page.route(`**/api/v1/evaluations/${evaluation.id}/preparations`, async route => {
    const response = await route.fetch(), payload = await response.json()
    attempts.push({ key: route.request().headers()['idempotency-key'], preparationId: payload.id, status: response.status() })
    if (attempts.length === 1) await route.abort('failed')
    else await route.fulfill({ response })
  })
  await selectDicom(page)
  await page.getByRole('button', { name: 'Cargar DICOM', exact: true }).click()
  await expect(page.locator('#preparation-error')).toBeVisible()
  await expect(page.locator('#dicom-file')).toBeEnabled()
  await page.getByRole('button', { name: 'Cargar DICOM', exact: true }).click()
  await waitForSource(page)
  expect(attempts).toHaveLength(2)
  expect(attempts[0]!.preparationId).toBe(attempts[1]!.preparationId)
  expect(attempts[0]!.key).toBeTruthy()
  expect(attempts[0]!.key).toBe(attempts[1]!.key)
  expect(attempts.map(item => item.status)).toEqual([202, 200])
})

test('a lost reference response keeps its key and cannot overwrite the already sealed center', async ({ page }) => {
  await createCase(page); const preparation = await upload(page); await fillReference(page)
  const attempts: { key: string | undefined; body: unknown; status: number; id?: string }[] = []
  await page.route(`**/api/v1/preparations/${preparation.id}/reference`, async route => {
    const response = await route.fetch(), payload = await response.json()
    attempts.push({ key: route.request().headers()['idempotency-key'], body: route.request().postDataJSON(), status: response.status(), id: payload.id })
    if (attempts.length === 1) await route.abort('failed')
    else await route.fulfill({ response })
  })
  await page.locator('#seal-reference').click()
  await expect(page.locator('#preparation-error')).toBeVisible()
  await expect(page.locator('#reference-center-x')).toHaveValue('200')
  await page.locator('#reference-center-x').fill('201')
  await page.locator('#seal-reference').click()
  await expect.poll(() => attempts.length).toBe(2)
  expect(attempts[1]!.status).toBe(409)
  await expect(page.locator('#reference-center-x')).toHaveValue('201')
  await page.locator('#reference-center-x').fill('200')
  await page.locator('#seal-reference').click()
  await expect(page.locator('#continue-quality-review')).toBeEnabled()
  expect(attempts).toHaveLength(3)
  expect(attempts.every(item => item.key === attempts[0]!.key)).toBe(true)
  expect(attempts[2]!.status).toBe(200)
  expect(attempts[2]!.id).toBe(attempts[0]!.id)
  const stored = await (await page.request.get(`/api/v1/preparations/${preparation.id}`)).json()
  expect(stored.sourceReference.centerXY).toEqual([200, 120])
})
